const validacion = $input.first();
const config = $('Configurar Caso Clinico').first().json;

let valido = true;
let resumen = '';

try {
  const content = validacion.json?.choices?.[0]?.message?.content ?? '{"valido":true}';
  const parsed = JSON.parse(content);
  valido = parsed.valido !== false;
  resumen = parsed.resumen_caso ?? config.caso_clinico.substring(0, 120) + '...';
} catch(e) {
  // Si gemma no pudo parsear JSON, continúa igual
  resumen = config.caso_clinico.substring(0, 120) + '...';
}

if (!valido) {
  throw new Error('Caso clínico inválido o incompleto. Verifica el input.');
}

return [{
  json: {
    caso_clinico: config.caso_clinico,
    resumen_caso: resumen,
    paciente_nombre: config.paciente_nombre,
    litellm_url: config.litellm_url,
    litellm_key: config.litellm_key,
    validacion_ok: true
  }
}];

