  respuestas_r1.push({ especialista: esp.nombre, rol: esp.rol, modelo: esp.modelo, respuesta });
  discusion_r1 += `--- ${esp.nombre} [${esp.modelo}] (${esp.rol}) ---\n${respuesta}\n\n`;
}

